import java.text.Normalizer;
import java.util.List;
import java.util.Set;

public record CustomerFilter(String nameFilter, Set<CustomerStatus> statuses) {

    public static CustomerFilter empty() {
        return new CustomerFilter("", Set.of());
    }

    public boolean matches(Customer customer) {
        return matchesName(customer) && matchesStatus(customer);
    }

    private boolean matchesName(Customer customer) {
        if (nameFilter == null || nameFilter.isBlank()) {
            return true;
        }
        String[] terms = nameFilter.trim().split("\\s+");
        String customerName = (customer.firstName() + " " + customer.lastName()).toLowerCase();
        String normalizedName = removeAccents(customerName);
        for (String term : terms) {
            String normalizedTerm = removeAccents(term.toLowerCase());
            if (!normalizedName.contains(normalizedTerm)) {
                return false;
            }
        }
        return true;
    }

    private boolean matchesStatus(Customer customer) {
        if (statuses == null || statuses.isEmpty()) {
            return true;
        }
        return statuses.contains(customer.status());
    }

    private static String removeAccents(String input) {
        String nfd = Normalizer.normalize(input, Normalizer.Form.NFD);
        return nfd.replaceAll("[^\\p{ASCII}]", "");
    }
}
